import { selectPreferredStripeApiFetch } from './api';
/**
 * Makes an authenticated API request to the Stripe API through the Dashboard session.
 * Automatically selects the best available transport mechanism.
 *
 * @param path - The API path or full URL to request.
 * @param options - Optional request configuration.
 * @returns A promise resolving to the serialized response.
 * @public
 */
export const stripeApiFetch = async (path, options) => {
    const preferredFetchMethod = await selectPreferredStripeApiFetch();
    return preferredFetchMethod(path, options);
};
