import { useEffect } from 'react';
import { getExtRouter } from './internal/getExtRouter';
import { useRoutesConfig } from './internal/useRoutesConfig';
/**
 * Performs an immediate navigation to a specified route by replacing
 * the URL in history so the user never sees the intermediate route.
 *
 * Requires a NavigationProvider higher up in the React tree.
 *
 * @see https://docs.stripe.com/stripe-apps/routing
 */
export function Redirect({ route }) {
    const router = getExtRouter();
    const config = useRoutesConfig();
    useEffect(() => {
        router.setRoute(config, route, { replace: true });
    }, [route, router, config]);
    return null;
}
